const findMaxPointIndex = (
  array,
  rangeStartIndex,
  rangeEndIndex,
  originalLength
) => {

  const middleIndex =
    rangeStartIndex + parseInt((rangeEndIndex - rangeStartIndex) / 2)

  if (
    (middleIndex === 0 || array[middleIndex - 1] <= array[middleIndex]) &&
    (middleIndex === originalLength - 1 ||
      array[middleIndex + 1] <= array[middleIndex])
  ) {
    return middleIndex
  } else if (middleIndex > 0 && array[middleIndex - 1] > array[middleIndex]) {
    return findMaxPointIndex(
      array,
      rangeStartIndex,
      middleIndex - 1,
      originalLength
    )
  } else {

    return findMaxPointIndex(
      array,
      middleIndex + 1,
      rangeEndIndex,
      originalLength
    )
  }
}

const LocalMaximumPoint = (A) => findMaxPointIndex(A, 0, A.length - 1, A.length)

export { LocalMaximumPoint }

const IsMaximumPoint = (array, index) => {

  if (index === 0) {
    return array[index] > array[index + 1]

  } else if (index === array.length - 1) {
    return array[index] > array[index - 1]

  } else {
    return array[index] > array[index + 1] && array[index] > array[index - 1]
  }
}

const CountLocalMaximumPoints = (array, startIndex, endIndex) => {

  if (startIndex === endIndex) {
    return IsMaximumPoint(array, startIndex) ? 1 : 0
  }

  const middleIndex = parseInt((startIndex + endIndex) / 2)
  return (
    CountLocalMaximumPoints(array, startIndex, middleIndex) +
    CountLocalMaximumPoints(array, middleIndex + 1, endIndex)
  )
}

const NumberOfLocalMaximumPoints = (A) =>
  CountLocalMaximumPoints(A, 0, A.length - 1)

export { NumberOfLocalMaximumPoints }

function QuickSelect(items, kth) {
  if (kth < 1 || kth > items.length) {
    throw new RangeError('Index Out of Bound')
  }

  return RandomizedSelect(items, 0, items.length - 1, kth)
}

function RandomizedSelect(items, left, right, i) {
  if (left === right) return items[left]

  const pivotIndex = RandomizedPartition(items, left, right)
  const k = pivotIndex - left + 1

  if (i === k) return items[pivotIndex]
  if (i < k) return RandomizedSelect(items, left, pivotIndex - 1, i)

  return RandomizedSelect(items, pivotIndex + 1, right, i - k)
}

function RandomizedPartition(items, left, right) {
  const rand = getRandomInt(left, right)
  Swap(items, rand, right)
  return Partition(items, left, right)
}

function Partition(items, left, right) {
  const x = items[right]
  let pivotIndex = left - 1

  for (let j = left; j < right; j++) {
    if (items[j] <= x) {
      pivotIndex++
      Swap(items, pivotIndex, j)
    }
  }

  Swap(items, pivotIndex + 1, right)

  return pivotIndex + 1
}

function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min
}

function Swap(arr, x, y) {
  ;[arr[x], arr[y]] = [arr[y], arr[x]]
}

export { QuickSelect }

const Reverse = (arr) => {

  for (let i = 0, j = arr.length - 1; i < arr.length / 2; i++, j--)
    [arr[i], arr[j]] = [arr[j], arr[i]]

  return arr
}
export { Reverse }

function detectCycle(head) {

  if (!head) {
    return false
  }

  let slow = head
  let fast = head.next
  while (fast && fast.next) {
    if (fast === slow) {
      return true
    }
    fast = fast.next.next
    slow = slow.next
  }
  return false
}

export { detectCycle }

import { LinkedList } from './SinglyLinkedList.js'

function mergeLinkedLists(list1, list2) {
  const mergedList = new LinkedList()

  let current1 = list1.headNode
  let current2 = list2.headNode

  while (current1 || current2) {
    if (!current1) {
      mergedList.addLast(current2.data)
      current2 = current2.next
    } else if (!current2) {
      mergedList.addLast(current1.data)
      current1 = current1.next
    } else {
      if (current1.data < current2.data) {
        mergedList.addLast(current1.data)
        current1 = current1.next
      } else {
        mergedList.addLast(current2.data)
        current2 = current2.next
      }
    }
  }

  return mergedList
}

export { mergeLinkedLists }

class ReverseSinglyLinkedList {
  solution(head) {
    let prev = null
    let next = null
    while (head) {
      next = head.next
      head.next = prev
      prev = head
      head = next
    }
    return prev
  }
}
export { ReverseSinglyLinkedList }

class Queue {
  constructor() {
    this.inputStack = []
    this.outputStack = []
  }

  enqueue(item) {
    this.inputStack.push(item)
  }

  dequeue() {

    this.outputStack = []
    while (this.inputStack.length > 0) {
      this.outputStack.push(this.inputStack.pop())
    }

    if (this.outputStack.length > 0) {
      const top = this.outputStack.pop()

      this.inputStack = []
      while (this.outputStack.length > 0) {
        this.inputStack.push(this.outputStack.pop())
      }
      return top
    }
  }
}

export { Queue }

class Stack {
  constructor() {

    this.top = 0

    this.stack = []
  }

  push(value) {
    this.stack[this.top] = value
    this.top++
  }

  pop() {
    if (this.top === 0) {
      return 'Stack is Empty'
    }

    this.top--
    const result = this.stack[this.top]
    this.stack = this.stack.splice(0, this.top)
    return result
  }

  size() {
    return this.top
  }

  peek() {
    return this.stack[this.top - 1]
  }

  view(output = (value) => console.log(value)) {
    for (let i = 0; i < this.top; i++) {
      output(this.stack[i])
    }
  }
}

export { Stack }

class Stack {
  constructor() {
    this.stack = []
    this.top = 0
  }

  push(newValue) {
    this.stack.push(newValue)
    this.top += 1
  }

  pop() {
    if (this.top !== 0) {
      this.top -= 1
      return this.stack.pop()
    }
    throw new Error('Stack Underflow')
  }

  get length() {
    return this.top
  }

  get isEmpty() {
    return this.top === 0
  }

  get last() {
    if (this.top !== 0) {
      return this.stack[this.stack.length - 1]
    }
    return null
  }

  static isStack(el) {
    return el instanceof Stack
  }
}

export { Stack }

export const catalanNumbers = (n) => {
  if (n === 0) {
    return [1]
  }
  const catList = [1, 1]

  for (let i = 2; i <= n; i++) {
    let newNumber = 0
    for (let j = 0; j < i; j++) {
      newNumber += catList[j] * catList[i - j - 1]
    }
    catList.push(newNumber)
  }

  return catList
}

const climbStairs = (n) => {
  let prev = 0
  let cur = 1
  let temp

  for (let i = 0; i < n; i++) {
    temp = prev
    prev = cur
    cur += temp
  }
  return cur
}

export { climbStairs }

export const change = (coins, amount) => {

  const combinations = new Array(amount + 1).fill(0)
  combinations[0] = 1

  for (let i = 0; i < coins.length; i++) {

    for (let j = coins[i]; j < combinations.length; j++) {
      combinations[j] += combinations[j - coins[i]]
    }
  }
  return combinations[amount]
}

export const coinChangeMin = (coins, amount) => {
  const map = { 0: 1 }
  for (let i = 1; i <= amount; i++) {
    let min = Infinity
    for (const coin of coins) {
      if (i < coin) continue
      min = Math.min(min, 1 + map[i - coin])
    }
    map[i] = min
  }
  return map[amount] === Infinity ? -1 : map[amount] - 1
}

const minimumEditDistance = (word1, word2) => {
  const n = word1.length
  const m = word2.length
  const dp = new Array(m + 1).fill(0).map((item) => [])

  for (let i = 0; i < n + 1; i++) {
    dp[0][i] = i
  }

  for (let i = 0; i < m + 1; i++) {
    dp[i][0] = i
  }

  for (let i = 1; i < m + 1; i++) {
    for (let j = 1; j < n + 1; j++) {
      const letter1 = word1[j - 1]
      const letter2 = word2[i - 1]

      if (letter1 === letter2) {
        dp[i][j] = dp[i - 1][j - 1]
      } else {
        dp[i][j] = Math.min(dp[i - 1][j], dp[i - 1][j - 1], dp[i][j - 1]) + 1
      }
    }
  }

  return dp[m][n]
}

