export default class Circle {
  constructor(radius) {
    this.radius = radius
  }

  perimeter = () => {
    return this.radius * 2 * Math.PI
  }

  area = () => {
    return Math.pow(this.radius, 2) * Math.PI
  }
}

export default class Cone {
  constructor(baseRadius, height) {
    this.baseRadius = baseRadius
    this.height = height
  }

  baseArea = () => {
    return Math.pow(this.baseRadius, 2) * Math.PI
  }

  volume = () => {
    return (this.baseArea() * this.height * 1) / 3
  }

  surfaceArea = () => {
    return (
      this.baseArea() +
      Math.PI *
        this.baseRadius *
        Math.sqrt(Math.pow(this.baseRadius, 2) + Math.pow(this.height, 2))
    )
  }
}

export default class Pyramid {
  constructor(bsl, height) {
    this.bsl = bsl
    this.height = height
  }

  baseArea = () => {
    return Math.pow(this.bsl, 2)
  }

  volume = () => {
    return (this.baseArea() * this.height) / 3
  }

  surfaceArea = () => {
    return (
      this.baseArea() +
      ((this.bsl * 4) / 2) *
        Math.sqrt(Math.pow(this.bsl / 2, 2) + Math.pow(this.height, 2))
    )
  }
}

export default class Sphere {
  constructor(radius) {
    this.radius = radius
  }

  volume = () => {
    return (Math.pow(this.radius, 3) * Math.PI * 4) / 3
  }

  surfaceArea = () => {
    return Math.pow(this.radius, 2) * Math.PI * 4
  }
}

function BellmanFord(graph, V, E, src, dest) {

  const dis = Array(V).fill(Infinity)

  dis[src] = 0

  for (let i = 0; i < V - 1; i++) {
    for (let j = 0; j < E; j++) {
      if (dis[graph[j][0]] + graph[j][2] < dis[graph[j][1]]) {
        dis[graph[j][1]] = dis[graph[j][0]] + graph[j][2]
      }
    }
  }

  for (let i = 0; i < E; i++) {
    const x = graph[i][0]
    const y = graph[i][1]
    const weight = graph[i][2]
    if (dis[x] !== Infinity && dis[x] + weight < dis[y]) {
      return null
    }
  }
  for (let i = 0; i < V; i++) {
    if (i === dest) return dis[i]
  }
}

export { BellmanFord }

import Queue from '../Data-Structures/Queue/Queue'

export function breadthFirstSearch(graph, startingNode) {

  const visited = new Set()

  const queue = new Queue()
  queue.enqueue(startingNode)

  while (!queue.isEmpty()) {

    const node = queue.dequeue()

    if (!visited.has(node)) {

      visited.add(node)
      const neighbors = graph[node]

      for (let i = 0; i < neighbors.length; i++) {
        queue.enqueue(neighbors[i])
      }
    }
  }

  return visited
}

function solve(graph, s) {
  const solutions = {}
  solutions[s] = []
  solutions[s].dist = 0

  while (true) {
    let p = null
    let neighbor = null
    let dist = Infinity

    for (const n in solutions) {
      if (!solutions[n]) {
        continue
      }
      const ndist = solutions[n].dist
      const adj = graph[n]

      for (const a in adj) {
        if (solutions[a]) {
          continue
        }

        const d = adj[a] + ndist
        if (d < dist) {
          p = solutions[n]
          neighbor = a
          dist = d
        }
      }
    }

    if (dist === Infinity) {
      break
    }

    solutions[neighbor] = p.concat(neighbor)

    solutions[neighbor].dist = dist
  }

  return solutions
}

export { solve }

const FloydWarshall = (dist) => {

  const n = dist.length
  for (let k = 0; k < n; k++) {
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        if (dist[i][j] > dist[i][k] + dist[k][j]) {

          dist[i][j] = dist[i][k] + dist[k][j]
        }
      }
    }
  }
  return dist
}

export { FloydWarshall }

class Graph {

  constructor() {
    this.edges = []
  }

  addEdge(node1, node2) {

    this.edges.push({
      node1,
      node2
    })
  }

  nodeNeighbors(node) {

    const neighbors = new Set()
    for (const edge of this.edges) {

      if (edge.node1 === node && !neighbors.has(edge.node2)) {
        neighbors.add(edge.node2)
      } else if (edge.node2 === node && !neighbors.has(edge.node1)) {
        neighbors.add(edge.node1)
      }
    }
    return neighbors
  }
}

export { Graph }

const islands = (matrixGrid) => {
  const matrix = matrixGrid
  let counter = 0

  const flood = (row, col) => {
    if (row < 0 || col < 0) return 
    if (row >= matrix.length || col >= matrix[row].length) return 

    const tile = matrix[row][col]
    if (tile !== '1') return

    matrix[row][col] = '0'

    flood(row + 1, col) 
    flood(row - 1, col) 
    flood(row, col + 1) 
    flood(row, col - 1) 
  }

  for (let row = 0; row < matrix.length; row += 1) {
    for (let col = 0; col < matrix[row].length; col += 1) {
      const current = matrix[row][col]
      if (current === '1') {
        flood(row, col)
        counter += 1
      }
    }
  }
  return counter
}

export { islands }

