const BinaryConvert = (num) => {
  let power = 1
  let binary = 0

  while (num) {
    const rem = num % 2
    num = Math.floor(num / 2)
    binary = rem * power + binary
    power *= 10
  }

  return binary
}

export { BinaryConvert }

const exponent = (x, n) => {
  let answer = 1
  while (n > 0) {
    if (n % 2 !== 0) answer *= x
    n = Math.floor(n / 2)
    if (n > 0) x *= x
  }
  return answer
}

export { exponent }

export const binaryExponentiation = (a, n) => {

  if (n === 0) {
    return 1
  } else if (n % 2 === 1) {
    return binaryExponentiation(a, n - 1) * a
  } else {
    const b = binaryExponentiation(a, n / 2)
    return b * b
  }
}

import { calcFactorial } from './Factorial'

export const findBinomialCoefficient = (n, k) => {
  if (typeof n !== 'number' || typeof k !== 'number') {
    throw Error('Type of arguments must be number.')
  }
  if (n < 0 || k < 0) {
    throw Error('Arguments must be greater than zero.')
  }
  let product = 1
  for (let i = n; i > k; i--) {
    product *= i
  }
  return product / calcFactorial(n - k)
}

const findRoot = (a, b, func, numberOfIterations) => {

  const belongsToDomain = (x, f) => {
    const res = f(x)
    return !Number.isNaN(res)
  }
  if (!belongsToDomain(a, func) || !belongsToDomain(b, func))
    throw Error("Given interval is not a valid subset of function's domain")

  const hasRoot = (a, b, func) => {
    return func(a) * func(b) <= 0
  }
  if (hasRoot(a, b, func) === false) {
    throw Error(
      'Product f(a)*f(b) has to be negative so that Bolzano theorem is applied'
    )
  }

  const m = (a + b) / 2

  if (numberOfIterations === 0) {
    return m
  }

  const fm = func(m)
  const prod1 = fm * func(a)
  const prod2 = fm * func(b)

  if (prod2 <= 0) return findRoot(m, b, func, --numberOfIterations)

  return findRoot(a, m, func, --numberOfIterations)
}

export { findRoot }

const factorial = (n) => {
  let fact = 1
  while (n !== 0) {
    fact = fact * n
    n--
  }
  return fact
}

const CheckKishnamurthyNumber = (number) => {

  if (typeof number !== 'number') {
    throw new TypeError('Argument is not a number.')
  }
  if (number === 0) {
    return false
  }

  let sumOfAllDigitFactorial = 0

  let newNumber = number

  while (newNumber > 0) {
    const lastDigit = newNumber % 10

    sumOfAllDigitFactorial += factorial(lastDigit)
    newNumber = Math.floor(newNumber / 10)
  }

  return sumOfAllDigitFactorial === number
}

export { CheckKishnamurthyNumber }

