export const PrimeFactors = (n) => {

  const primeFactors = []
  for (let i = 2; i * i <= n; i++) {
    while (n % i === 0) {
      primeFactors.push(i)
      n = Math.floor(n / i)
    }
  }
  if (n > 1) {
    primeFactors.push(n)
  }
  return primeFactors
}

const quadraticRoots = (a, b, c) => {

  const discriminant = b * b - 4 * a * c

  if (discriminant < 0) {
    return []
  } else if (discriminant === 0) {

    return [-b / (2 * a)]
  } else {

    const sqrtDiscriminant = Math.sqrt(discriminant)
    return [
      (-b + sqrtDiscriminant) / (2 * a),
      (-b - sqrtDiscriminant) / (2 * a)
    ]
  }
}

