function zFunction(text) {
  const length = text.length
  const zArray = Array(length).fill(0)

  let left = 0
  let right = 0
  for (let index = 0; index < length; index++) {

    if (index <= right) {
      zArray[index] = Math.min(right - index + 1, zArray[index - left])
    }

    while (
      index + zArray[index] < length &&
      text[zArray[index]] === text[index + zArray[index]]
    ) {
      zArray[index]++
    }

    if (index + zArray[index] - 1 > right) {
      left = index
      right = index + zArray[index] - 1
    }
  }
  return zArray
}

export default zFunction

import { isLeapYear } from '../Maths/LeapYear'

const getMonthDays = (monthNumber, year) => {
  const the31DaysMonths = [1, 3, 5, 7, 8, 10, 12]
  const the30DaysMonths = [4, 6, 9, 11]

  if (
    !the31DaysMonths.includes(monthNumber) &&
    !the30DaysMonths.includes(monthNumber) &&
    monthNumber !== 2
  ) {
    throw new TypeError('Invalid Month Number.')
  }

  if (the31DaysMonths.includes(monthNumber)) {
    return 31
  }

  if (the30DaysMonths.includes(monthNumber)) {
    return 30
  }

  if (isLeapYear(year)) {
    return 29
  }

  return 28
}

export { getMonthDays }

